            ["Now you've made me blush."] = "dwarf-female\\npc_kissed_3.ogg",
            ["Safe and sound."] = "dwarf-female\\npc_landed_1.ogg",
            ["Good landing. I'll tell the birds."] = "dwarf-female\\npc_landed_2.ogg",
            ["Solid ground. Feels strange after all that sky."] = "dwarf-female\\npc_landed_3.ogg",
            ["Down we come. Legs still work? Good."] = "dwarf-female\\npc_landed_4.ogg",
            ["That was a fine flight."] = "dwarf-female\\npc_landed_5.ogg",
            ["Ha! Good one."] = "dwarf-female\\npc_laughAlong_1.ogg",
            ["Heh. You're funny."] = "dwarf-female\\npc_laughAlong_2.ogg",
            ["Ha! That laugh of yours is catching."] = "dwarf-female\\npc_laughAlong_3.ogg",
            ["There, you have it. Be pleased with yourself. Give the practice its credit, and give yourself time to feel what has become easier."] = "dwarf-female\\lore2879_learned_1.ogg",
            ["There is satisfaction in learning enough to find the next good teacher. Deneb Walker has a book worth seeking out, and Doctor VanHowzen can take a student's training further in Theramore. I am glad to point the way. Bring back what you can tell me of the experience. I shall enjoy hearing it."] = "dwarf-female\\lore5150_learned_1.ogg",
            ["A sharpening wheel can make a useful addition to a camp. Learn your craft, then give the work a proper place in the wilderness. Remember the campfire first. A cooking trainer can help with that. You would be surprised how quickly an ambitious plan can get ahead of its most basic preparations."] = "dwarf-female\\lore6300_learned_1.ogg",
            ["Learning something new? Good for you."] = "dwarf-female\\npc_learned_1.ogg",
            ["Always improving. I admire that."] = "dwarf-female\\npc_learned_2.ogg",
            ["Something new up your sleeve? I'll be watching."] = "dwarf-female\\npc_learned_3.ogg",
            ["The more you know, the better. That's what I always say."] = "dwarf-female\\npc_learned_4.ogg",
            ["Level {level}! Well done, {name}!"] = "dwarf-female\\npc_levelUp_1.ogg",
            ["Look at you, {name}. Level {level} already."] = "dwarf-female\\npc_levelUp_2.ogg",
            ["Level {level}! That calls for a cheer!"] = "dwarf-female\\npc_levelUp_3.ogg",
            ["Level {level}. I've seen a lot of adventurers come and go. You're one of the good ones."] = "dwarf-female\\npc_levelUp_4.ogg",
            ["Ha! Level {level}! Well earned."] = "dwarf-female\\npc_levelUp_5.ogg",
            ["Level {level}. Wait until I tell everyone back home."] = "dwarf-female\\npc_levelUp_6.ogg",
            ["Stronger every day. I can see it."] = "dwarf-female\\npc_levelUp_7.ogg",
            ["Another level! I knew you had it in you."] = "dwarf-female\\npc_levelUp_8.ogg",
            ["Well, look who's moving up in the world."] = "dwarf-female\\npc_levelUp_9.ogg",
            ["Another step up. Mind you don't get a big head."] = "dwarf-female\\npc_levelUp_10.ogg",
            ["A useful find? Good. Take a proper look before someone tells you a grand story about what it must be worth."] = "dwarf-female\\lore5512_loot_1.ogg",
            ["What an interesting little thing. Any idea what it was used for?"] = "dwarf-female\\lore8720_loot_1.ogg",
            ["{item}! Now that's a find."] = "dwarf-female\\npc_loot_1.ogg",
            ["Well, look at that. {item}."] = "dwarf-female\\npc_loot_2.ogg",
            ["{item}! Lucky day."] = "dwarf-female\\npc_loot_3.ogg",
            ["Ooh, what did you find?"] = "dwarf-female\\npc_loot_4.ogg",
            ["Anything good in there?"] = "dwarf-female\\npc_loot_5.ogg",
            ["Pockets full! Nice."] = "dwarf-female\\npc_loot_6.ogg",
            ["You're hurt! Get out of there!"] = "dwarf-female\\npc_lowHealth_1.ogg",
            ["Careful! You're nearly done in!"] = "dwarf-female\\npc_lowHealth_2.ogg",
            ["Back off and catch your breath!"] = "dwarf-female\\npc_lowHealth_3.ogg",
            ["You're bleeding! Fall back!"] = "dwarf-female\\npc_lowHealth_4.ogg",
            ["Get out of there!"] = "dwarf-female\\npc_lowHealth_5.ogg",
            ["Drink something! Anything!"] = "dwarf-female\\npc_lowHealth_6.ogg",
            ["This isn't worth dying over!"] = "dwarf-female\\npc_lowHealth_7.ogg",
            ["Run! I'll tell everyone you were brave!"] = "dwarf-female\\npc_lowHealth_8.ogg",
            ["Bandage! Potion! Something!"] = "dwarf-female\\npc_lowHealth_9.ogg",
            ["Hang on! Don't you dare go down!"] = "dwarf-female\\npc_lowHealth_10.ogg",
            ["A letter. I hope someone far away has remembered to write of the little things."] = "dwarf-female\\lore2695_mail_1.ogg",
            ["Looks like you've got mail."] = "dwarf-female\\npc_mail_1.ogg",
            ["Someone's written to you. How nice."] = "dwarf-female\\npc_mail_2.ogg",
            ["A letter! I hope it's good news."] = "dwarf-female\\npc_mail_3.ogg",
            ["Mail for you. Somebody's thinking of you."] = "dwarf-female\\npc_mail_4.ogg",
            ["Level {level}! There's nothing left to teach you, is there?"] = "dwarf-female\\npc_maxLevel_1.ogg",
            ["The very top! I'm honored to have come along for it."] = "dwarf-female\\npc_maxLevel_2.ogg",
            ["That's the peak. Where do you go from here? Anywhere you like, I suppose."] = "dwarf-female\\npc_maxLevel_3.ogg",
            ["Riding in style, I see."] = "dwarf-female\\npc_mount_1.ogg",
            ["Fine animal you've got there."] = "dwarf-female\\npc_mount_2.ogg",
            ["I'll just walk alongside, shall I?"] = "dwarf-female\\npc_mount_3.ogg",
            ["Now that's a proper way to travel."] = "dwarf-female\\npc_mount_4.ogg",
            ["Does it have a name? It looks like it should have a name."] = "dwarf-female\\npc_mount_5.ogg",
            ["{friend} seems friendly."] = "dwarf-female\\npc_newFriend_1.ogg",
            ["I've heard good things about {friend}."] = "dwarf-female\\npc_newFriend_2.ogg",
            ["Another friend! You collect them like coins."] = "dwarf-female\\npc_newFriend_3.ogg",
            ["Another friendly face. You're good at this."] = "dwarf-female\\npc_newFriend_4.ogg",
            ["You make friends faster than I make tea."] = "dwarf-female\\npc_newFriend_5.ogg",
            ["What is it? I don't see anything."] = "dwarf-female\\npc_pointToo_1.ogg",
            ["Where? Oh! No, I still don't see it."] = "dwarf-female\\npc_pointToo_2.ogg",
            ["Is it something good? Or something bad?"] = "dwarf-female\\npc_pointToo_3.ogg",
            ["Yes, {name}?"] = "dwarf-female\\npc_poke_1.ogg",
            ["Hm? Something on your mind?"] = "dwarf-female\\npc_poke_2.ogg",
            ["I'm right here."] = "dwarf-female\\npc_poke_3.ogg",
            ["Careful, now."] = "dwarf-female\\npc_poke_4.ogg",
            ["Ha! You're a funny one."] = "dwarf-female\\npc_poke_5.ogg",
            ["Need something?"] = "dwarf-female\\npc_poke_6.ogg",
            ["Still here, still with you."] = "dwarf-female\\npc_poke_7.ogg",
            ["What is it? Did you see something?"] = "dwarf-female\\npc_poke_8.ogg",
            ["If that's how you say hello where you're from, all right."] = "dwarf-female\\npc_poke_9.ogg",
            ["I'm listening."] = "dwarf-female\\npc_poke_10.ogg",
            ["Still breathing, if that's what you're checking."] = "dwarf-female\\npc_poke_11.ogg",
            ["Was that a poke or a question?"] = "dwarf-female\\npc_poke_12.ogg",
            ["Easy! I bruise like a peach."] = "dwarf-female\\npc_poke_13.ogg",
            ["You have my full attention. Mostly."] = "dwarf-female\\npc_poke_14.ogg",
            ["Hm? Sorry, I was miles away."] = "dwarf-female\\npc_poke_15.ogg",
            ["Ask away."] = "dwarf-female\\npc_poke_16.ogg",
            ["Ow. Was that necessary?"] = "dwarf-female\\npc_poke_17.ogg",
            ["What, did I miss something?"] = "dwarf-female\\npc_poke_18.ogg",
            ["Present and accounted for."] = "dwarf-female\\npc_poke_19.ogg",
            ["Yes, yes, I see you."] = "dwarf-female\\npc_poke_20.ogg",
            ["All right, all right, I'm awake!"] = "dwarf-female\\npc_pokeMany_1.ogg",
            ["Is this going to keep happening?"] = "dwarf-female\\npc_pokeMany_2.ogg",
            ["You'd think I was a doorbell."] = "dwarf-female\\npc_pokeMany_3.ogg",
            ["I'm starting to think you enjoy this."] = "dwarf-female\\npc_pokeMany_4.ogg",
            ["Enough! I surrender!"] = "dwarf-female\\npc_pokeMany_5.ogg",
            ["One more and I'm going home. I mean it. Probably."] = "dwarf-female\\npc_pokeMany_6.ogg",
            ["Please check on Remtravel if you are heading south. He can become so absorbed in a discovery that the surroundings seem to stop existing for him. They do not stop being dangerous. I came back to seek help, and I would be glad to hear that he is safe."] = "dwarf-female\\lore2913_quest_1.ogg",
            ["Well done. I hope someone gives you proper credit, as well as a reward."] = "dwarf-female\\lore7292_quest_1.ogg",
            ["Another job done. Nicely handled."] = "dwarf-female\\npc_quest_1.ogg",
            ["Well done! They'll be grateful."] = "dwarf-female\\npc_quest_2.ogg",
            ["You've a knack for helping folk."] = "dwarf-female\\npc_quest_3.ogg",
            ["That's one more person sleeping easier tonight."] = "dwarf-female\\npc_quest_4.ogg",
            ["Good work. Who's next?"] = "dwarf-female\\npc_quest_5.ogg",
            ["Word gets around. People will remember that."] = "dwarf-female\\npc_quest_6.ogg",
            ["Nicely done. Somebody's going to tell that story at the inn."] = "dwarf-female\\npc_quest_7.ogg",
            ["That's the way!"] = "dwarf-female\\npc_quest_8.ogg",
            ["You make it look easy."] = "dwarf-female\\npc_quest_9.ogg",
            ["Done and done. What's next?"] = "dwarf-female\\npc_quest_10.ogg",
            ["Another errand? I like your spirit."] = "dwarf-female\\npc_questAccepted_1.ogg",
            ["Off we go, then."] = "dwarf-female\\npc_questAccepted_2.ogg",
            ["Somebody's lucky you came along."] = "dwarf-female\\npc_questAccepted_3.ogg",
            ["Here we go again. I love it."] = "dwarf-female\\npc_questAccepted_4.ogg",
            ["Sounds like trouble. Count me in."] = "dwarf-female\\npc_questAccepted_5.ogg",
            ["Hm? Did I doze off?"] = "dwarf-female\\npc_reload_1.ogg",
            ["Strange. I could swear the world just blinked."] = "dwarf-female\\npc_reload_2.ogg",
            ["Where was I? Oh, right. With you."] = "dwarf-female\\npc_reload_3.ogg",
            ["Hm. I lost my train of thought. Something about the road."] = "dwarf-female\\npc_reload_4.ogg",
            ["A good place to rest our feet."] = "dwarf-female\\npc_rest_1.ogg",
            ["Nothing like a warm inn."] = "dwarf-female\\npc_rest_2.ogg",
            ["I could sit here all day."] = "dwarf-female\\npc_rest_3.ogg",
            ["A chair, a fire, good company. That's living."] = "dwarf-female\\npc_rest_4.ogg",
            ["Let's stay a moment. My feet insist."] = "dwarf-female\\npc_rest_5.ogg",
            ["Easy there, tiger."] = "dwarf-female\\npc_roarBack_1.ogg",
            ["Very fierce. I'm terrified."] = "dwarf-female\\npc_roarBack_2.ogg",
            ["Was that a roar or a yawn?"] = "dwarf-female\\npc_roarBack_3.ogg",
            ["Charming."] = "dwarf-female\\npc_rudeBack_1.ogg",
            ["I'll pretend I didn't see that."] = "dwarf-female\\npc_rudeBack_2.ogg",
            ["Well, I never! Actually, I have. But still."] = "dwarf-female\\npc_rudeBack_3.ogg",
            ["At your service."] = "dwarf-female\\npc_saluteBack_1.ogg",
            ["Sir! Or madam."] = "dwarf-female\\npc_saluteBack_2.ogg",
            ["Standing ready!"] = "dwarf-female\\npc_saluteBack_3.ogg",
            ["Oh, it's {friend}! Say hello for me."] = "dwarf-female\\npc_seeFriend_1.ogg",
            ["{friend}! Good to see a friendly face."] = "dwarf-female\\npc_seeFriend_2.ogg",
            ["Look who it is! Give them a wave."] = "dwarf-female\\npc_seeFriend_3.ogg",
            ["Oh, I know them! Small world."] = "dwarf-female\\npc_seeFriend_4.ogg",
            ["No need to be shy."] = "dwarf-female\\npc_shyToo_1.ogg",
            ["Aw, don't hide."] = "dwarf-female\\npc_shyToo_2.ogg",
            ["You're among friends here."] = "dwarf-female\\npc_shyToo_3.ogg",
            ["Don't mind if I do."] = "dwarf-female\\npc_sitToo_1.ogg",
            ["Good idea. My knees agree."] = "dwarf-female\\npc_sitToo_2.ogg",
            ["Ah, that's better."] = "dwarf-female\\npc_sitToo_3.ogg",
            ["Oh, don't start. That is catching. All right, just a moment. You can call it checking that we have both settled."] = "dwarf-female\\lore11069_sleepToo_1.ogg",
            ["I could use a nap myself."] = "dwarf-female\\npc_sleepToo_1.ogg",
            ["Wake me when it's time to go."] = "dwarf-female\\npc_sleepToo_2.ogg",
            ["A nap does sound nice."] = "dwarf-female\\npc_sleepToo_3.ogg",
            ["Up we go! Never gets old."] = "dwarf-female\\npc_taxi_1.ogg",
            ["Look at it all down there."] = "dwarf-female\\npc_taxi_2.ogg",
            ["A good gryphon is worth its weight in gold."] = "dwarf-female\\npc_taxi_3.ogg",
            ["Hold on tight!"] = "dwarf-female\\npc_taxi_4.ogg",
            ["I'll never get tired of this view."] = "dwarf-female\\npc_taxi_5.ogg",
            ["Don't look down. Actually, do. It's lovely."] = "dwarf-female\\npc_taxi_6.ogg",
            ["The wind up here! Hold on to your hat."] = "dwarf-female\\npc_taxi_7.ogg",
            ["Anytime."] = "dwarf-female\\npc_thanked_1.ogg",
            ["Happy to help."] = "dwarf-female\\npc_thanked_2.ogg",
            ["Don't mention it."] = "dwarf-female\\npc_thanked_3.ogg",
            ["{friend} thinks of you as {tier} now. I'm not surprised."] = "dwarf-female\\npc_tier_1.ogg",
            ["Making friends everywhere you go, aren't you?"] = "dwarf-female\\npc_tier_2.ogg",
            ["People really warm to you, don't they?"] = "dwarf-female\\npc_tier_3.ogg",
            ["That friendship's growing. Nice to see."] = "dwarf-female\\npc_tier_4.ogg",
            ["Hello!"] = "dwarf-female\\npc_waveBack_1.ogg",
            ["Hi there!"] = "dwarf-female\\npc_waveBack_2.ogg",
            ["Well, hello to you too."] = "dwarf-female\\npc_waveBack_3.ogg",
            ["Right back at you!"] = "dwarf-female\\npc_waveBack_4.ogg",
            ["New streets, new corners. Give me a moment to hear what this place sounds like."] = "dwarf-female\\lore5109_zone_1.ogg",
            ["So this is {zone}."] = "dwarf-female\\npc_zone_1.ogg",
            ["{zone}, eh? Lead on."] = "dwarf-female\\npc_zone_2.ogg",
            ["I haven't been to {zone} in years."] = "dwarf-female\\npc_zone_3.ogg",
            ["{zone}. Stay sharp."] = "dwarf-female\\npc_zone_4.ogg",
            ["Ah, {zone}. Look at that view."] = "dwarf-female\\npc_zone_5.ogg",
            ["New place, new faces."] = "dwarf-female\\npc_zone_6.ogg",
            ["Keep your eyes open. I don't know these parts."] = "dwarf-female\\npc_zone_7.ogg",
            ["I've only ever heard stories about this place."] = "dwarf-female\\npc_zone_8.ogg",
            ["Look at it all. Worth the walk."] = "dwarf-female\\npc_zone_9.ogg",
            ["Smells different here. Not bad, just different."] = "dwarf-female\\npc_zone_10.ogg",
            ["I'd better remember the way back."] = "dwarf-female\\npc_zone_11.ogg",
            ["Well, this is a change of scenery."] = "dwarf-female\\npc_zone_12.ogg",
        },
        ["dwarf-male"] = {
            ["Welcome back!"] = "dwarf-male\\npc_alive_1.ogg",
            ["There you are. Gave me a fright."] = "dwarf-male\\npc_alive_2.ogg",
            ["Back on your feet! Good."] = "dwarf-male\\npc_alive_3.ogg",
            ["Good as new. Well, nearly."] = "dwarf-male\\npc_alive_4.ogg",
            ["Don't scare me like that again."] = "dwarf-male\\npc_alive_5.ogg",
            ["Bravo!"] = "dwarf-male\\npc_applaudToo_1.ogg",
            ["Well done!"] = "dwarf-male\\npc_applaudToo_2.ogg",
            ["Encore!"] = "dwarf-male\\npc_applaudToo_3.ogg",
            ["I'll wait here."] = "dwarf-male\\npc_away_1.ogg",
            ["Take your time. I'm not going anywhere."] = "dwarf-male\\npc_away_2.ogg",
            ["I'll keep an eye on things."] = "dwarf-male\\npc_away_3.ogg",
            ["Off you go. I'll mind the spot."] = "dwarf-male\\npc_away_4.ogg",
            ["Wake me if anything exciting happens."] = "dwarf-male\\npc_away_5.ogg",
            ["There you are."] = "dwarf-male\\npc_back_1.ogg",
            ["Welcome back."] = "dwarf-male\\npc_back_2.ogg",
            ["Ah, you're back. Shall we?"] = "dwarf-male\\npc_back_3.ogg",
            ["Ah, good. I was starting to talk to myself."] = "dwarf-male\\npc_back_4.ogg",
            ["Ready? Me too."] = "dwarf-male\\npc_back_5.ogg",
            ["Next time we're in Ironforge, leave a few keepsakes with me. Give your shoulders a chance."] = "dwarf-male\\lore2461_bagsFull_1.ogg",
            ["Your bags are bursting. Time to sell a few things."] = "dwarf-male\\npc_bagsFull_1.ogg",
            ["No room left? I know a merchant or two."] = "dwarf-male\\npc_bagsFull_2.ogg",
            ["You're carrying half the countryside."] = "dwarf-male\\npc_bagsFull_3.ogg",
            ["Your pack's going to split at the seams."] = "dwarf-male\\npc_bagsFull_4.ogg",
            ["Glad to have you along. There's room for you in the company, and you needn't earn it twice."] = "dwarf-male\\lore1246_befriended_1.ogg",
            ["I would be glad of your company. You remember the little things, and those make a long road more agreeable. Walk beside me and tell me how your day has gone. We can admire our tracks along the way, provided we keep anything that needs delivering moving."] = "dwarf-male\\lore12738_befriended_1.ogg",
            ["You hear me out, and you tell me when I've said enough. A useful friend, and a welcome one."] = "dwarf-male\\lore13843_befriended_1.ogg",
            ["You don't insist on filling every quiet moment. I like that about your company."] = "dwarf-male\\lore14363_befriended_1.ogg",
            ["Good company, you are. You can ask the way as often as you need. I won't start counting."] = "dwarf-male\\lore14365_befriended_1.ogg",
            ["Good to have you along. We can make room for a laugh or two on the way."] = "dwarf-male\\lore14367_befriended_1.ogg",
            ["You came looking for me? Aye, I'm pleased. Come on, my friend. There's room beside you for an old pair of clumsy boots."] = "dwarf-male\\lore1472_befriended_1.ogg",
            ["You came to bring me along. Aye, I am pleased, my friend. Come on. There is room for another voice in the conversation."] = "dwarf-male\\lore1478_befriended_1.ogg",
            ["A friend! Huzzah! No voucher needed. I'm delighted you came back."] = "dwarf-male\\lore14842_befriended_1.ogg",
            ["A road with good company calls for a cheer; I'll gladly come walking, I'm happy you're here. No need for a flourish, no grand thing to do; A pleasant old ramble will suit me and you."] = "dwarf-male\\lore239_befriended_1.ogg",
            ["You're smiling before I've said anything. Now that's a welcome worth keeping."] = "dwarf-male\\lore2460_befriended_1.ogg",
            ["You make time for the fellow behind the counter. That's a fine thing to find in a friend."] = "dwarf-male\\lore2461_befriended_1.ogg",
            ["Ye thought to bring me along. Gladly, friend. Come on. A little company improves the road, and I should like to hear what ye have been making of it."] = "dwarf-male\\lore268238_befriended_1.ogg",
            ["Ye'd like me along? Gladly, friend. Lead on. We can share a tune, or a bit of conversation. I'm pleased to have the company either way."] = "dwarf-male\\lore277721_befriended_1.ogg",
            ["You want me along? Aye, then. You've made your choice, friend. Come on. I can offer company and a very good account of how I ought to have won the last argument."] = "dwarf-male\\lore4961_befriended_1.ogg",
            ["Good company, you are. We can leave the sales talk at the counter for a while."] = "dwarf-male\\lore5107_befriended_1.ogg",
            ["You check whether I've had a share, too. That's the sort of friend I like beside me."] = "dwarf-male\\lore5124_befriended_1.ogg",
            ["You came to bring me along. Aye, I am pleased, my friend. Let us see what we can learn from the road together."] = "dwarf-male\\lore5413_befriended_1.ogg",
            ["You came to bring me along. Aye, I am glad, my friend. Let us find somewhere with a good view and no hurry to leave it."] = "dwarf-male\\lore5510_befriended_1.ogg",
            ["You came to take me along! Aye, I am glad, my friend. Let us see what good work we have been walking past all this time."] = "dwarf-male\\lore5511_befriended_1.ogg",
            ["You came to bring me along. Aye, I am pleased, my friend. It is good to have some company with time to stay. Come on, then."] = "dwarf-male\\lore6173_befriended_1.ogg",
            ["Well, you've done more than lend a hand and hurry off. You came back for the company. I appreciate that. Let us take a walk together, and if there's a favor to be done on the way, we'll see it fairly settled between us."] = "dwarf-male\\lore658_befriended_1.ogg",
            ["I'd come along. You're good company, and a walk will give us something new to look at. You can tell me what you've learned on the way. I'll try to let you finish before I explain how I'd have done it. Try, mind."] = "dwarf-male\\lore6966_befriended_1.ogg",
            ["I would enjoy coming along. It is pleasant to see something beyond the next customer and hear how the day treats a friend. Tell me where we are headed. I shall take an interest in the company as well as how well our gear stands up to the journey."] = "dwarf-male\\lore836_befriended_1.ogg",
            ["Good to see you outside the auction house. No lot to sell, no bid to place. Just company."] = "dwarf-male\\lore8671_befriended_1.ogg",
            ["Likewise."] = "dwarf-male\\npc_bowBack_1.ogg",
            ["An honor."] = "dwarf-male\\npc_bowBack_2.ogg",
            ["The pleasure's mine."] = "dwarf-male\\npc_bowBack_3.ogg",
            ["{friend} is your Buddy now? The more the merrier!"] = "dwarf-male\\npc_buddy_1.ogg",
            ["Another Buddy. Should I be jealous?"] = "dwarf-male\\npc_buddy_2.ogg",
            ["Another Buddy! Your circle's getting crowded."] = "dwarf-male\\npc_buddy_3.ogg",
            ["Good choice. I'd vouch for them."] = "dwarf-male\\npc_buddy_4.ogg",
            ["Hooray!"] = "dwarf-male\\npc_cheerAlong_1.ogg",
            ["Huzzah!"] = "dwarf-male\\npc_cheerAlong_2.ogg",
            ["Three cheers!"] = "dwarf-male\\npc_cheerAlong_3.ogg",
            ["Who are you calling chicken?"] = "dwarf-male\\npc_chickenBack_1.ogg",
            ["Bawk yourself."] = "dwarf-male\\npc_chickenBack_2.ogg",
            ["I'm brave! I'm just brave quietly."] = "dwarf-male\\npc_chickenBack_3.ogg",
            ["Everyone still here? Good. Let us keep it that way. We can decide who tells the best version once we are safely out of trouble."] = "dwarf-male\\lore1478_combatEnd_1.ogg",
            ["There. A moment to breathe. If this becomes a story, I expect ye to remember that I was impressively composed throughout. More or less. We needn't argue over every detail."] = "dwarf-male\\lore4961_combatEnd_1.ogg",
            ["Everyone all right? Have a proper look before we move on. The work can wait a moment while we make sure nobody needs help."] = "dwarf-male\\lore6173_combatEnd_1.ogg",
            ["Well fought!"] = "dwarf-male\\npc_combatEnd_1.ogg",
            ["That's how it's done."] = "dwarf-male\\npc_combatEnd_2.ogg",
            ["Everyone in one piece? Good."] = "dwarf-male\\npc_combatEnd_3.ogg",
            ["Ha! They won't try that again."] = "dwarf-male\\npc_combatEnd_4.ogg",
            ["I'll admit, my heart was pounding."] = "dwarf-male\\npc_combatEnd_5.ogg",
            ["Nicely done."] = "dwarf-male\\npc_combatEnd_6.ogg",
            ["Is it over? It's over. Good."] = "dwarf-male\\npc_combatEnd_7.ogg",
            ["Remind me never to make you angry."] = "dwarf-male\\npc_combatEnd_8.ogg",
            ["Not bad at all!"] = "dwarf-male\\npc_combatEnd_9.ogg",
            ["Victory! I'll be telling everyone about that one."] = "dwarf-male\\npc_combatEnd_10.ogg",
            ["Catch your breath. You earned it."] = "dwarf-male\\npc_combatEnd_11.ogg",
            ["And not a scratch on me. Thanks to you."] = "dwarf-male\\npc_combatEnd_12.ogg",
            ["Hold on, it's weakening!"] = "dwarf-male\\npc_combatLong_1.ogg",
            ["Don't give up now!"] = "dwarf-male\\npc_combatLong_2.ogg",
            ["Steady. Steady."] = "dwarf-male\\npc_combatLong_3.ogg",
            ["This one's stubborn. Keep at it!"] = "dwarf-male\\npc_combatLong_4.ogg",
            ["It's tiring! I can see it!"] = "dwarf-male\\npc_combatLong_5.ogg",
            ["Long fight. You've got more in you."] = "dwarf-male\\npc_combatLong_6.ogg",
            ["Keep at it!"] = "dwarf-male\\npc_combatMid_1.ogg",
            ["Good hit!"] = "dwarf-male\\npc_combatMid_2.ogg",
            ["Watch your back!"] = "dwarf-male\\npc_combatMid_3.ogg",
            ["That's it, that's it!"] = "dwarf-male\\npc_combatMid_4.ogg",
            ["You've got it on the run!"] = "dwarf-male\\npc_combatMid_5.ogg",
            ["Don't let up!"] = "dwarf-male\\npc_combatMid_6.ogg",
            ["Ha! Did you see that?"] = "dwarf-male\\npc_combatMid_7.ogg",
            ["Nearly there!"] = "dwarf-male\\npc_combatMid_8.ogg",
            ["Hit it again!"] = "dwarf-male\\npc_combatMid_9.ogg",
            ["It's on its last legs!"] = "dwarf-male\\npc_combatMid_10.ogg",
            ["Mind your footing!"] = "dwarf-male\\npc_combatMid_11.ogg",
            ["That one's going to leave a mark!"] = "dwarf-male\\npc_combatMid_12.ogg",
            ["Go on! Go on!"] = "dwarf-male\\npc_combatMid_13.ogg",
            ["You make this look like a dance!"] = "dwarf-male\\npc_combatMid_14.ogg",
            ["Swing that blade! Go on!"] = "dwarf-male\\npc_combatMid_15.ogg",
            ["Into the thick of it! That's the way!"] = "dwarf-male\\npc_combatMid_16.ogg",
            ["The Light's with you! Now hit it!"] = "dwarf-male\\npc_combatMid_17.ogg",
            ["Let your pet have a go!"] = "dwarf-male\\npc_combatMid_18.ogg",
            ["Nice shot! Right on target!"] = "dwarf-male\\npc_combatMid_19.ogg",
            ["Where'd you go? Oh! There you are! Stab it!"] = "dwarf-male\\npc_combatMid_20.ogg",
            ["Patch yourself up, then smite it!"] = "dwarf-male\\npc_combatMid_21.ogg",
            ["Call the storm down on it!"] = "dwarf-male\\npc_combatMid_22.ogg",
            ["Burn it! Burn it all! Well, just that one."] = "dwarf-male\\npc_combatMid_23.ogg",
            ["Whatever that green fire is, keep doing it!"] = "dwarf-male\\npc_combatMid_24.ogg",
            ["Turn into something big and scary!"] = "dwarf-male\\npc_combatMid_25.ogg",
            ["Look out!"] = "dwarf-male\\npc_combatStart_1.ogg",
            ["Here they come!"] = "dwarf-male\\npc_combatStart_2.ogg",
            ["Give them what for!"] = "dwarf-male\\npc_combatStart_3.ogg",
            ["Stay sharp!"] = "dwarf-male\\npc_combatStart_4.ogg",
            ["On your guard!"] = "dwarf-male\\npc_combatStart_5.ogg",
            ["Here we go again!"] = "dwarf-male\\npc_combatStart_6.ogg",
            ["Watch it, it's coming right at you!"] = "dwarf-male\\npc_combatStart_7.ogg",
            ["Show them what you've got!"] = "dwarf-male\\npc_combatStart_8.ogg",
            ["Chin up. It'll be all right."] = "dwarf-male\\npc_comforted_1.ogg",
            ["I'm here if you need me."] = "dwarf-male\\npc_comforted_2.ogg",
            ["Thank you. I needed that."] = "dwarf-male\\npc_comforted_3.ogg",
            ["Right, then! Give me a moment to persuade the boots."] = "dwarf-male\\lore14367_danceAlong_1.ogg",
            ["Aye, that's the tune! Give me a little room. If I get the turn right, you are allowed to look impressed."] = "dwarf-male\\lore1472_danceAlong_1.ogg",
            ["Ha! All right, I'll dance."] = "dwarf-male\\npc_danceAlong_1.ogg",
            ["I haven't danced in ages!"] = "dwarf-male\\npc_danceAlong_2.ogg",
            ["Well, if you insist!"] = "dwarf-male\\npc_danceAlong_3.ogg",
            ["Watch my feet. Or don't."] = "dwarf-male\\npc_danceAlong_4.ogg",
            ["Easy now. Let's get you back on your feet."] = "dwarf-male\\npc_died_1.ogg",
            ["That looked like it hurt."] = "dwarf-male\\npc_died_2.ogg",
            ["Don't worry. Happens to the best of us."] = "dwarf-male\\npc_died_3.ogg",
            ["We'll come back stronger."] = "dwarf-male\\npc_died_4.ogg",
            ["Oh, that's not good."] = "dwarf-male\\npc_died_5.ogg",
            ["Well. That could have gone better."] = "dwarf-male\\npc_died_6.ogg",
            ["Let's agree that one didn't count."] = "dwarf-male\\npc_died_7.ogg",
            ["Lie still. I'll keep watch."] = "dwarf-male\\npc_died_8.ogg",
            ["Keep close in here."] = "dwarf-male\\npc_dungeon_1.ogg",
            ["I don't like the look of this place."] = "dwarf-male\\npc_dungeon_2.ogg",
            ["Watch your step. And your back."] = "dwarf-male\\npc_dungeon_3.ogg",
            ["It's dark in here. I don't love the dark."] = "dwarf-male\\npc_dungeon_4.ogg",
            ["Stay together. Nobody wander off."] = "dwarf-male\\npc_dungeon_5.ogg",
            ["Very impressive."] = "dwarf-male\\npc_flexBack_1.ogg",
            ["Don't hurt yourself."] = "dwarf-male\\npc_flexBack_2.ogg",
            ["Put those away before someone gets hurt."] = "dwarf-male\\npc_flexBack_3.ogg",
            ["Try the grip and how it sits. Then think about carrying it for a while. The right choice should be useful after the fine first impression has settled into an ordinary day's work."] = "dwarf-male\\lore268238_gear_1.ogg",
            ["New armor? Walk a few steps. Sit down. Good. Now tell me how it feels."] = "dwarf-male\\lore5107_gear_1.ogg",
            ["A useful piece. See how it sits, and notice where it needs looking after. Fine-looking gear still has work to do once you step outside. I like a thing that serves its wearer well, whether it is new from the stock or familiar enough to have a story."] = "dwarf-male\\lore836_gear_1.ogg",
            ["That looks good on you."] = "dwarf-male\\npc_gear_1.ogg",
            ["New armor? Very sharp."] = "dwarf-male\\npc_gear_2.ogg",
            ["You'll turn heads in that."] = "dwarf-male\\npc_gear_3.ogg",
            ["Shiny! Did you polish that yourself?"] = "dwarf-male\\npc_gear_4.ogg",
            ["That suits you. Very heroic."] = "dwarf-male\\npc_gear_5.ogg",
            ["Now you look the part."] = "dwarf-male\\npc_gear_6.ogg",
            ["Come on, your body's this way."] = "dwarf-male\\npc_ghost_1.ogg",
            ["I'll walk with you. Don't mind the chill."] = "dwarf-male\\npc_ghost_2.ogg",
            ["You look a bit see-through. It's fine. Mostly fine."] = "dwarf-male\\npc_ghost_3.ogg",
            ["Follow the road. I'll be right here."] = "dwarf-male\\npc_ghost_4.ogg",
            ["Is it cold, being a ghost? You look cold."] = "dwarf-male\\npc_ghost_5.ogg",
            ["Aye, I'm ready. Packed an extra cup. Must have counted wrong again."] = "dwarf-male\\lore1246_greet_1.ogg",
            ["There you are. Hands cold? That is why a hot delivery matters. A little care on the road can make a fine difference to the person waiting at the other end. And once they are finished appreciating it, they can appreciate bringing the mug back as well."] = "dwarf-male\\lore12738_greet_1.ogg",
            ["Ready to move? Good. I'll keep the instructions brief. That is my intention, at least."] = "dwarf-male\\lore13843_greet_1.ogg",
            ["Ready. We can talk, or just walk a while. Both are agreeable."] = "dwarf-male\\lore14363_greet_1.ogg",
            ["Aye, I'll walk with you. Say if you want the long explanation or just the next turning."] = "dwarf-male\\lore14365_greet_1.ogg",
            ["Ready! A steady pace, unless you've a good tune in mind."] = "dwarf-male\\lore14367_greet_1.ogg",
            ["Ah, there you are! A walk sounds good. These boots could use something straightforward to do for a change."] = "dwarf-male\\lore1472_greet_1.ogg",
            ["Ah, there you are, friend. Come on, then. A walk, a little conversation, and perhaps a seat somewhere warm. We needn't earn the seat by surviving anything first."] = "dwarf-male\\lore1478_greet_1.ogg",
            ["Step right up! A splendid outing awaits! All right, all right, I can say it more quietly."] = "dwarf-male\\lore14842_greet_1.ogg",
            ["A friend on the road! Now that's a fine sight. You've arrived just in time for a verse done right. Pull up for a moment and tell me your tale. I'll listen as gladly as I fuss over ale."] = "dwarf-male\\lore239_greet_1.ogg",
            ["Come along, friend! Today's welcome comes with no queue at all."] = "dwarf-male\\lore2460_greet_1.ogg",
            ["There you are! Pack a little lighter this time, did you?"] = "dwarf-male\\lore2461_greet_1.ogg",
            ["Ready for a walk? Good. The kit is in order, and the cup is where I like it. Come on, friend. Tell me what ye have seen since we last had a proper talk."] = "dwarf-male\\lore268238_greet_1.ogg",
            ["There ye are, friend. Fancy a walk? I've a pleasant tune for company. I remember the next part now, though I may take me own turn when we come to it. Hum along if ye like."] = "dwarf-male\\lore277721_greet_1.ogg",
            ["There ye are. Come on, then. I've thought of a better answer to a conversation that was over some time ago. You can tell me whether it was worth the wait."] = "dwarf-male\\lore4961_greet_1.ogg",
            ["Ready. If anything pinches on the first hill, say so. No prizes for putting up with it."] = "dwarf-male\\lore5107_greet_1.ogg",
            ["Off somewhere? Tell me how many we're feeding, and I'll come along."] = "dwarf-male\\lore5124_greet_1.ogg",
            ["Ah, my friend! A walk sounds good. Tell me what you have been finding. An unusual material can give a smith a great deal to think about."] = "dwarf-male\\lore5413_greet_1.ogg",
            ["Ah, my friend. A walk sounds good. Keep an ear open. The Foreman may have something to say about our leaving. A bird, before you ask."] = "dwarf-male\\lore5510_greet_1.ogg",
            ["Ah, my friend! A walk would be grand. If I stop to admire a hinge, you are welcome to ask why. I have been waiting for someone to ask."] = "dwarf-male\\lore5511_greet_1.ogg",
            ["Ah, there you are, friend. Good to see you on your feet. Come on, then. Tell me how you have been, and don't leave the important part until the end. I mean whether you're all right."] = "dwarf-male\\lore6173_greet_1.ogg",
            ["There you are! Ready to put your feet to use? A bit of honest work goes easier with company, and I could do with a stretch myself. Mind your gloves. Cold fingers make a poor start to an errand, however willing the rest of you might be."] = "dwarf-male\\lore658_greet_1.ogg",
            ["There you are. Learned anything useful since I saw you? Take a moment and tell me. I may even manage a whole conversation before I offer an opinion. Don't look so doubtful. I'm capable of considerable restraint when I put my mind to it."] = "dwarf-male\\lore6966_greet_1.ogg",
            ["Come in, come in. No need to bring the whole chill of the valley with you. Have a look at what you need, and take a moment to feel your fingers again. If someone arrives with a scalding mornbrew, I may be persuaded to call that excellent timing."] = "dwarf-male\\lore836_greet_1.ogg",
            ["A walk without a bidding crowd. Aye, that sounds very agreeable."] = "dwarf-male\\lore8671_greet_1.ogg",
            ["Lead the way, {name}."] = "dwarf-male\\npc_greet_1.ogg",
            ["Glad to come along, {name}!"] = "dwarf-male\\npc_greet_2.ogg",
            ["Where are we off to today?"] = "dwarf-male\\npc_greet_3.ogg",
            ["I told the others I'd be out for a while. Let's make it count."] = "dwarf-male\\npc_greet_4.ogg",
            ["It's good to get away from the counter for once."] = "dwarf-male\\npc_greet_5.ogg",
            ["Ready when you are, {name}."] = "dwarf-male\\npc_greet_6.ogg",
            ["Some fresh air will do me good."] = "dwarf-male\\npc_greet_7.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "dwarf-male\\npc_greet_8.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "dwarf-male\\npc_greet_9.ogg",
            ["Right behind you. Where to first?"] = "dwarf-male\\npc_greet_10.ogg",
            ["I packed a lunch. Just in case."] = "dwarf-male\\npc_greet_11.ogg",
            ["Off on an adventure! Don't tell my boss."] = "dwarf-male\\npc_greet_12.ogg",
            ["Fresh boots, fresh start. Let's go."] = "dwarf-male\\npc_greet_13.ogg",
            ["I've been looking forward to this all week."] = "dwarf-male\\npc_greet_14.ogg",
            ["Everyone know where we're headed? Good to ask before we set off."] = "dwarf-male\\lore14365_group_1.ogg",
            ["More company! Wonderful."] = "dwarf-male\\npc_group_1.ogg",
            ["Strength in numbers."] = "dwarf-male\\npc_group_2.ogg",
            ["New faces! Hello, everyone."] = "dwarf-male\\npc_group_3.ogg",
            ["A whole party. Now it's an adventure."] = "dwarf-male\\npc_group_4.ogg",
            ["Home again!"] = "dwarf-male\\npc_hearth_1.ogg",
            ["Off to the inn. My treat. Well, your treat."] = "dwarf-male\\npc_hearth_2.ogg",
            ["Home sweet home."] = "dwarf-male\\npc_hearth_3.ogg",
            ["Back to a warm bed. Finally."] = "dwarf-male\\npc_hearth_4.ogg",
            ["Oh! Well. That's nice."] = "dwarf-male\\npc_hugged_1.ogg",
            ["Aw, thank you."] = "dwarf-male\\npc_hugged_2.ogg",
            ["Oh, you big softie."] = "dwarf-male\\npc_hugged_3.ogg",
            ["Tally teaches me something new most days. A good reason to keep turning up, that."] = "dwarf-male\\lore1246_idle_1.ogg",
            ["Look back a moment. A neat row of bootprints, all the way across that fresh patch. I like seeing where I have been before the wind takes it away. No, I have not lost my way. I am allowed to enjoy a little of the road I travel."] = "dwarf-male\\lore12738_idle_1.ogg",
            ["A clear instruction, properly understood, saves a good deal of marching in the wrong direction."] = "dwarf-male\\lore13843_idle_1.ogg",
            ["A poem about an uneventful round? Aye. An uneventful round is a fine thing to have."] = "dwarf-male\\lore14363_idle_1.ogg",
            ["That is the forge on my map. Yes, it looks like a kettle. You remembered it, though."] = "dwarf-male\\lore14365_idle_1.ogg",
            ["The boots? Aye, they're heavy. I still can't blame them for every missed step."] = "dwarf-male\\lore14367_idle_1.ogg",
            ["I got the turn right. Once. I'd show you, but give me a moment to remember what I did with the other foot."] = "dwarf-male\\lore1472_idle_1.ogg",
            ["I leave a pause where Christoph always objects. Know every word he'll say. Still, the tale wouldn't sound right without him interrupting it. Don't tell him I said so. He'll expect me to pause longer."] = "dwarf-male\\lore1478_idle_1.ogg",
            ["That serious fellow was smiling. I saw it. A fine result for an afternoon's work."] = "dwarf-male\\lore14842_idle_1.ogg",
            ["A toast can be polished till silver would shine; I worked on the words till I lost the next line. Then out came a greeting, quite simple and true: I'm glad of this company. Especially you."] = "dwarf-male\\lore239_idle_1.ogg",
            ["Why did the copper cross the counter? No, wait. I've forgotten the good part."] = "dwarf-male\\lore2460_idle_1.ogg",
            ["A copper on its edge can be more interesting than a mountain of gold."] = "dwarf-male\\lore2461_idle_1.ogg",
            ["I packed the whole kit until nothing rattled. Very tidy. Then I missed the little tap of me tin cup. I've let that one sound back in. The rest of the kit can continue to behave itself."] = "dwarf-male\\lore268238_idle_1.ogg",
            ["I forgot the next part of a tune once, so I let the walk suggest something. I remember the proper bit now. Still like me own turn sometimes. It has come to feel at home on the walk."] = "dwarf-male\\lore277721_idle_1.ogg",
            ["That was not quite what I said at the time. It is what I should have said, and it improves the story considerably. If ye noticed the difference, we can keep that between ourselves."] = "dwarf-male\\lore4961_idle_1.ogg",
            ["Soft slippers are recovery equipment. I'll defend that description as long as necessary."] = "dwarf-male\\lore5107_idle_1.ogg",
            ["There's always someone who says they aren't hungry until everyone else starts eating."] = "dwarf-male\\lore5124_idle_1.ogg",
            ["I hope someone improves on my work. Would it sting? A little. Then I would want the notes. All the notes. There is no sense letting pride waste a good discovery."] = "dwarf-male\\lore5413_idle_1.ogg",
            ["I call the bird Foreman. Always above the work, with a very loud opinion about it. I am rather fond of him. Don't tell him; he'll expect a raise."] = "dwarf-male\\lore5510_idle_1.ogg",
            ["An ordinary hinge, aye. Look how well it does its little job. Someone gave that a great deal of thought. I should like to have met them."] = "dwarf-male\\lore5511_idle_1.ogg",
            ["I have tried to think of a proper thank-you for Henze. Comes out as a grumble every time. I hope he'll hear what I mean under it. Relief can be a clumsy thing to put into words."] = "dwarf-male\\lore6173_idle_1.ogg",
            ["Now, if I carry the curl back around there... no, that makes the whole name look like a ram has walked through the ink. Just a bit of writing practice. Nothing urgent. You needn't stare quite so hard; I know perfectly well what it says."] = "dwarf-male\\lore658_idle_1.ogg",
            ["A certificate's a scrap of paper until someone has worked for it. Then you see how they hold it. I might straighten an edge before handing one over. No harm in letting a fellow have a tidy reminder of something he kept at."] = "dwarf-male\\lore6966_idle_1.ogg",
            ["That old scarf? Not for sale. It has gone soft with use, and I like the feel of it. A new thing can be fine work, but there is something agreeable about a familiar comfort. You need not put a price on everything you are pleased to keep."] = "dwarf-male\\lore836_idle_1.ogg",
            ["No, I didn't bargain over breakfast. The baker was up before either of us."] = "dwarf-male\\lore8671_idle_1.ogg",
            ["Nice day for it."] = "dwarf-male\\npc_idle_1.ogg",
            ["{zone} is lovely this time of year."] = "dwarf-male\\npc_idle_2.ogg",
            ["Don't mind me. I'm enjoying the company."] = "dwarf-male\\npc_idle_3.ogg",
            ["You know, I don't get out nearly enough."] = "dwarf-male\\npc_idle_4.ogg",
            ["My feet are already sore. In a good way."] = "dwarf-male\\npc_idle_5.ogg",
            ["I wonder how things are back home without me."] = "dwarf-male\\npc_idle_6.ogg",
            ["Every road looks different when you're not working."] = "dwarf-male\\npc_idle_7.ogg",
            ["Have you ever just stopped and listened to the wind?"] = "dwarf-male\\npc_idle_8.ogg",
            ["I could get used to this."] = "dwarf-male\\npc_idle_9.ogg",
            ["Don't tell anyone, but this beats standing in one spot all day."] = "dwarf-male\\npc_idle_10.ogg",
            ["If you need a hand, just say the word."] = "dwarf-male\\npc_idle_11.ogg",
            ["Good company makes the miles shorter."] = "dwarf-male\\npc_idle_12.ogg",
            ["Mind if I stretch? Old bones."] = "dwarf-male\\npc_idle_13.ogg",
            ["Getting late. The stars will be out soon."] = "dwarf-male\\npc_idle_14.ogg",
            ["Quiet night. I like quiet nights."] = "dwarf-male\\npc_idle_15.ogg",
            ["We've been at it for a while. You're tireless, you know that?"] = "dwarf-male\\npc_idle_16.ogg",
            ["I used to wonder what was past the next hill. Now I know: another hill."] = "dwarf-male\\npc_idle_17.ogg",
            ["Do you ever get used to all this walking?"] = "dwarf-male\\npc_idle_18.ogg",
            ["I've heard stories about you, you know. Some of them are even nice."] = "dwarf-male\\npc_idle_19.ogg",
            ["Smell that? Somebody's cooking something good nearby."] = "dwarf-male\\npc_idle_20.ogg",
            ["If anyone asks, I'm on important business."] = "dwarf-male\\npc_idle_21.ogg",
            ["You're easy company. I mean that kindly."] = "dwarf-male\\npc_idle_22.ogg",
            ["I keep thinking I left something on the stove."] = "dwarf-male\\npc_idle_23.ogg",
            ["Look at that sky."] = "dwarf-male\\npc_idle_24.ogg",
            ["Back home they'll never believe where I've been."] = "dwarf-male\\npc_idle_25.ogg",
            ["I should have brought a better pair of boots."] = "dwarf-male\\npc_idle_26.ogg",
            ["Funny how a quiet road can feel like a holiday."] = "dwarf-male\\npc_idle_27.ogg",
            ["Do adventurers ever take a day off? Asking for a friend. The friend is me."] = "dwarf-male\\npc_idle_28.ogg",
            ["I've counted twelve birds since we set out. Thirteen. Never mind."] = "dwarf-male\\npc_idle_29.ogg",
            ["One of these days you'll have to tell me how you got started."] = "dwarf-male\\npc_idle_30.ogg",
            ["You can tell a lot about someone by how they walk. You walk like you mean it."] = "dwarf-male\\npc_idle_31.ogg",
            ["I'm not complaining. I'm just saying my feet have opinions."] = "dwarf-male\\npc_idle_32.ogg",
            ["Sorry, I've had the same tune stuck in my head all day."] = "dwarf-male\\npc_idle_33.ogg",
            ["If we pass a merchant, remind me I need thread."] = "dwarf-male\\npc_idle_34.ogg",
            ["I wonder what the folks back home are gossiping about."] = "dwarf-male\\npc_idle_35.ogg",
            ["Every time I think I've seen it all, you take me somewhere new."] = "dwarf-male\\npc_idle_36.ogg",
            ["It's peaceful out here. Until it isn't."] = "dwarf-male\\npc_idle_37.ogg",
            ["I could do with a cup of something warm."] = "dwarf-male\\npc_idle_38.ogg",
            ["Morning air's the best air."] = "dwarf-male\\npc_idle_39.ogg",
            ["Early start, eh? I approve."] = "dwarf-male\\npc_idle_40.ogg",
            ["The light's going gold. Best time of day."] = "dwarf-male\\npc_idle_41.ogg",
            ["Stars are out. Makes you feel small, doesn't it?"] = "dwarf-male\\npc_idle_42.ogg",
            ["Shouldn't we both be in bed by now?"] = "dwarf-male\\npc_idle_43.ogg",
            ["Long day. Good day, though."] = "dwarf-male\\npc_idle_44.ogg",
            ["Still going? I'll say this for you: you don't quit."] = "dwarf-male\\npc_idle_45.ogg",
            ["Ha! I'll have to remember that one."] = "dwarf-male\\npc_jokeBack_1.ogg",
            ["Oh, that's terrible. Tell it again."] = "dwarf-male\\npc_jokeBack_2.ogg",
            ["I'm stealing that one."] = "dwarf-male\\npc_jokeBack_3.ogg",
            ["Oh my."] = "dwarf-male\\npc_kissed_1.ogg",
            ["Well, I never."] = "dwarf-male\\npc_kissed_2.ogg",
            ["Now you've made me blush."] = "dwarf-male\\npc_kissed_3.ogg",
            ["Safe and sound."] = "dwarf-male\\npc_landed_1.ogg",
            ["Good landing. I'll tell the birds."] = "dwarf-male\\npc_landed_2.ogg",
            ["Solid ground. Feels strange after all that sky."] = "dwarf-male\\npc_landed_3.ogg",
            ["Down we come. Legs still work? Good."] = "dwarf-male\\npc_landed_4.ogg",
            ["That was a fine flight."] = "dwarf-male\\npc_landed_5.ogg",
            ["Ha! Good one."] = "dwarf-male\\npc_laughAlong_1.ogg",
            ["Heh. You're funny."] = "dwarf-male\\npc_laughAlong_2.ogg",
            ["Ha! That laugh of yours is catching."] = "dwarf-male\\npc_laughAlong_3.ogg",
            ["There you go! Knowing how is a fine start. Now put it to use."] = "dwarf-male\\lore1246_learned_1.ogg",
            ["Good! Now tell me what you found difficult, and what made it work. I may learn something from the way you reached the answer."] = "dwarf-male\\lore5413_learned_1.ogg",
            ["There ye are! Now try it with your own hands while the lesson is fresh. I do like seeing a good idea become useful work."] = "dwarf-male\\lore5511_learned_1.ogg",
            ["There. You kept at it until something made sense. Remember which part changed for you. Next time it seems impossible, that'll be worth more than standing about wishing your hands belonged to someone cleverer."] = "dwarf-male\\lore6966_learned_1.ogg",
            ["Learning something new? Good for you."] = "dwarf-male\\npc_learned_1.ogg",
            ["Always improving. I admire that."] = "dwarf-male\\npc_learned_2.ogg",
            ["Something new up your sleeve? I'll be watching."] = "dwarf-male\\npc_learned_3.ogg",
            ["The more you know, the better. That's what I always say."] = "dwarf-male\\npc_learned_4.ogg",
            ["A splendid achievement! Let the company hear it! Huzzah!"] = "dwarf-male\\lore14842_levelUp_1.ogg",
            ["Level {level}! Well done, {name}!"] = "dwarf-male\\npc_levelUp_1.ogg",
            ["Look at you, {name}. Level {level} already."] = "dwarf-male\\npc_levelUp_2.ogg",
            ["Level {level}! That calls for a cheer!"] = "dwarf-male\\npc_levelUp_3.ogg",
            ["Level {level}. I've seen a lot of adventurers come and go. You're one of the good ones."] = "dwarf-male\\npc_levelUp_4.ogg",
            ["Ha! Level {level}! Well earned."] = "dwarf-male\\npc_levelUp_5.ogg",
            ["Level {level}. Wait until I tell everyone back home."] = "dwarf-male\\npc_levelUp_6.ogg",
            ["Stronger every day. I can see it."] = "dwarf-male\\npc_levelUp_7.ogg",
            ["Another level! I knew you had it in you."] = "dwarf-male\\npc_levelUp_8.ogg",
            ["Well, look who's moving up in the world."] = "dwarf-male\\npc_levelUp_9.ogg",
            ["Another step up. Mind you don't get a big head."] = "dwarf-male\\npc_levelUp_10.ogg",
            ["{item}! Now that's a find."] = "dwarf-male\\npc_loot_1.ogg",
            ["Well, look at that. {item}."] = "dwarf-male\\npc_loot_2.ogg",
            ["{item}! Lucky day."] = "dwarf-male\\npc_loot_3.ogg",
            ["Ooh, what did you find?"] = "dwarf-male\\npc_loot_4.ogg",
            ["Anything good in there?"] = "dwarf-male\\npc_loot_5.ogg",
            ["Pockets full! Nice."] = "dwarf-male\\npc_loot_6.ogg",
            ["You're hurt! Get out of there!"] = "dwarf-male\\npc_lowHealth_1.ogg",
            ["Careful! You're nearly done in!"] = "dwarf-male\\npc_lowHealth_2.ogg",
            ["Back off and catch your breath!"] = "dwarf-male\\npc_lowHealth_3.ogg",
            ["You're bleeding! Fall back!"] = "dwarf-male\\npc_lowHealth_4.ogg",
            ["Get out of there!"] = "dwarf-male\\npc_lowHealth_5.ogg",
            ["Drink something! Anything!"] = "dwarf-male\\npc_lowHealth_6.ogg",
            ["This isn't worth dying over!"] = "dwarf-male\\npc_lowHealth_7.ogg",
            ["Run! I'll tell everyone you were brave!"] = "dwarf-male\\npc_lowHealth_8.ogg",
            ["Bandage! Potion! Something!"] = "dwarf-male\\npc_lowHealth_9.ogg",
            ["Hang on! Don't you dare go down!"] = "dwarf-male\\npc_lowHealth_10.ogg",
            ["Letters, eh? Have a proper look at the name before setting off with them. A stack can travel a fair distance and still have one fellow waiting for his share. And if you're writing back, leave enough room for the address after your magnificent signature."] = "dwarf-male\\lore658_mail_1.ogg",
            ["A sale, perhaps. Read the notice before you start spending the proceeds."] = "dwarf-male\\lore8671_mail_1.ogg",
            ["Looks like you've got mail."] = "dwarf-male\\npc_mail_1.ogg",
            ["Someone's written to you. How nice."] = "dwarf-male\\npc_mail_2.ogg",
            ["A letter! I hope it's good news."] = "dwarf-male\\npc_mail_3.ogg",
            ["Mail for you. Somebody's thinking of you."] = "dwarf-male\\npc_mail_4.ogg",
            ["Level {level}! There's nothing left to teach you, is there?"] = "dwarf-male\\npc_maxLevel_1.ogg",
            ["The very top! I'm honored to have come along for it."] = "dwarf-male\\npc_maxLevel_2.ogg",
            ["That's the peak. Where do you go from here? Anywhere you like, I suppose."] = "dwarf-male\\npc_maxLevel_3.ogg",
            ["Riding in style, I see."] = "dwarf-male\\npc_mount_1.ogg",
            ["Fine animal you've got there."] = "dwarf-male\\npc_mount_2.ogg",
            ["I'll just walk alongside, shall I?"] = "dwarf-male\\npc_mount_3.ogg",
            ["Now that's a proper way to travel."] = "dwarf-male\\npc_mount_4.ogg",
            ["Does it have a name? It looks like it should have a name."] = "dwarf-male\\npc_mount_5.ogg",
            ["{friend} seems friendly."] = "dwarf-male\\npc_newFriend_1.ogg",
            ["I've heard good things about {friend}."] = "dwarf-male\\npc_newFriend_2.ogg",
            ["Another friend! You collect them like coins."] = "dwarf-male\\npc_newFriend_3.ogg",
            ["Another friendly face. You're good at this."] = "dwarf-male\\npc_newFriend_4.ogg",
            ["You make friends faster than I make tea."] = "dwarf-male\\npc_newFriend_5.ogg",
            ["What is it? I don't see anything."] = "dwarf-male\\npc_pointToo_1.ogg",
            ["Where? Oh! No, I still don't see it."] = "dwarf-male\\npc_pointToo_2.ogg",
            ["Is it something good? Or something bad?"] = "dwarf-male\\npc_pointToo_3.ogg",
            ["Yes, {name}?"] = "dwarf-male\\npc_poke_1.ogg",
            ["Hm? Something on your mind?"] = "dwarf-male\\npc_poke_2.ogg",
            ["I'm right here."] = "dwarf-male\\npc_poke_3.ogg",
            ["Careful, now."] = "dwarf-male\\npc_poke_4.ogg",
            ["Ha! You're a funny one."] = "dwarf-male\\npc_poke_5.ogg",
            ["Need something?"] = "dwarf-male\\npc_poke_6.ogg",
            ["Still here, still with you."] = "dwarf-male\\npc_poke_7.ogg",
            ["What is it? Did you see something?"] = "dwarf-male\\npc_poke_8.ogg",
            ["If that's how you say hello where you're from, all right."] = "dwarf-male\\npc_poke_9.ogg",
            ["I'm listening."] = "dwarf-male\\npc_poke_10.ogg",
            ["Still breathing, if that's what you're checking."] = "dwarf-male\\npc_poke_11.ogg",
            ["Was that a poke or a question?"] = "dwarf-male\\npc_poke_12.ogg",
            ["Easy! I bruise like a peach."] = "dwarf-male\\npc_poke_13.ogg",
            ["You have my full attention. Mostly."] = "dwarf-male\\npc_poke_14.ogg",
            ["Hm? Sorry, I was miles away."] = "dwarf-male\\npc_poke_15.ogg",
            ["Ask away."] = "dwarf-male\\npc_poke_16.ogg",
            ["Ow. Was that necessary?"] = "dwarf-male\\npc_poke_17.ogg",
            ["What, did I miss something?"] = "dwarf-male\\npc_poke_18.ogg",
            ["Present and accounted for."] = "dwarf-male\\npc_poke_19.ogg",
            ["Yes, yes, I see you."] = "dwarf-male\\npc_poke_20.ogg",
            ["All right, all right, I'm awake!"] = "dwarf-male\\npc_pokeMany_1.ogg",
            ["Is this going to keep happening?"] = "dwarf-male\\npc_pokeMany_2.ogg",
            ["You'd think I was a doorbell."] = "dwarf-male\\npc_pokeMany_3.ogg",
            ["I'm starting to think you enjoy this."] = "dwarf-male\\npc_pokeMany_4.ogg",
            ["Enough! I surrender!"] = "dwarf-male\\npc_pokeMany_5.ogg",
            ["One more and I'm going home. I mean it. Probably."] = "dwarf-male\\npc_pokeMany_6.ogg",
            ["There, a job followed through. People remember more than the thing you delivered. They remember whether you took care with it, whether you listened, and whether you brought back what belonged to someone else. Especially that last part. Some of us have a limited supply of mugs."] = "dwarf-male\\lore12738_quest_1.ogg",
            ["Assignment completed. Good. Give a clear report of what happened."] = "dwarf-male\\lore13843_quest_1.ogg",
            ["Another job done. Nicely handled."] = "dwarf-male\\npc_quest_1.ogg",
            ["Well done! They'll be grateful."] = "dwarf-male\\npc_quest_2.ogg",
            ["You've a knack for helping folk."] = "dwarf-male\\npc_quest_3.ogg",
            ["That's one more person sleeping easier tonight."] = "dwarf-male\\npc_quest_4.ogg",
            ["Good work. Who's next?"] = "dwarf-male\\npc_quest_5.ogg",
            ["Word gets around. People will remember that."] = "dwarf-male\\npc_quest_6.ogg",
            ["Nicely done. Somebody's going to tell that story at the inn."] = "dwarf-male\\npc_quest_7.ogg",
            ["That's the way!"] = "dwarf-male\\npc_quest_8.ogg",
            ["You make it look easy."] = "dwarf-male\\npc_quest_9.ogg",
            ["Done and done. What's next?"] = "dwarf-male\\npc_quest_10.ogg",
            ["Another errand? I like your spirit."] = "dwarf-male\\npc_questAccepted_1.ogg",
            ["Off we go, then."] = "dwarf-male\\npc_questAccepted_2.ogg",
            ["Somebody's lucky you came along."] = "dwarf-male\\npc_questAccepted_3.ogg",
            ["Here we go again. I love it."] = "dwarf-male\\npc_questAccepted_4.ogg",
            ["Sounds like trouble. Count me in."] = "dwarf-male\\npc_questAccepted_5.ogg",
            ["Hm? Did I doze off?"] = "dwarf-male\\npc_reload_1.ogg",
            ["Strange. I could swear the world just blinked."] = "dwarf-male\\npc_reload_2.ogg",
            ["Where was I? Oh, right. With you."] = "dwarf-male\\npc_reload_3.ogg",
            ["Hm. I lost my train of thought. Something about the road."] = "dwarf-male\\npc_reload_4.ogg",
            ["A quiet seat and a little time. I may write a line or two."] = "dwarf-male\\lore14363_rest_1.ogg",
            ["A pause on the road and a place for our feet; There's plenty of pleasure in finding a seat. I could think of a toast, but the plain words will do: It's good to be sitting and talking with you."] = "dwarf-male\\lore239_rest_1.ogg",
            ["Sit a while. You can tell me what's on your mind before I try another joke."] = "dwarf-male\\lore2460_rest_1.ogg",
            ["A pause would be pleasant. Sit a moment, friend. No need to fill it all at once. We've time for whatever ye would like to say, and I can let the tune wait its turn."] = "dwarf-male\\lore277721_rest_1.ogg",
            ["Come sit down. I've allowed for the one who was certain they wouldn't want anything."] = "dwarf-male\\lore5124_rest_1.ogg",
            ["A good place to rest our feet."] = "dwarf-male\\npc_rest_1.ogg",
            ["Nothing like a warm inn."] = "dwarf-male\\npc_rest_2.ogg",
            ["I could sit here all day."] = "dwarf-male\\npc_rest_3.ogg",
            ["A chair, a fire, good company. That's living."] = "dwarf-male\\npc_rest_4.ogg",
            ["Let's stay a moment. My feet insist."] = "dwarf-male\\npc_rest_5.ogg",
            ["Easy there, tiger."] = "dwarf-male\\npc_roarBack_1.ogg",
            ["Very fierce. I'm terrified."] = "dwarf-male\\npc_roarBack_2.ogg",
            ["Was that a roar or a yawn?"] = "dwarf-male\\npc_roarBack_3.ogg",
            ["Charming."] = "dwarf-male\\npc_rudeBack_1.ogg",
            ["I'll pretend I didn't see that."] = "dwarf-male\\npc_rudeBack_2.ogg",
            ["Well, I never! Actually, I have. But still."] = "dwarf-male\\npc_rudeBack_3.ogg",
            ["At your service."] = "dwarf-male\\npc_saluteBack_1.ogg",
            ["Sir! Or madam."] = "dwarf-male\\npc_saluteBack_2.ogg",
            ["Standing ready!"] = "dwarf-male\\npc_saluteBack_3.ogg",
            ["Oh, it's {friend}! Say hello for me."] = "dwarf-male\\npc_seeFriend_1.ogg",
            ["{friend}! Good to see a friendly face."] = "dwarf-male\\npc_seeFriend_2.ogg",
            ["Look who it is! Give them a wave."] = "dwarf-male\\npc_seeFriend_3.ogg",
            ["Oh, I know them! Small world."] = "dwarf-male\\npc_seeFriend_4.ogg",
            ["No need to be shy."] = "dwarf-male\\npc_shyToo_1.ogg",
            ["Aw, don't hide."] = "dwarf-male\\npc_shyToo_2.ogg",
            ["You're among friends here."] = "dwarf-male\\npc_shyToo_3.ogg",
            ["Don't mind if I do."] = "dwarf-male\\npc_sitToo_1.ogg",
            ["Good idea. My knees agree."] = "dwarf-male\\npc_sitToo_2.ogg",
            ["Ah, that's better."] = "dwarf-male\\npc_sitToo_3.ogg",
            ["I could use a nap myself."] = "dwarf-male\\npc_sleepToo_1.ogg",
            ["Wake me when it's time to go."] = "dwarf-male\\npc_sleepToo_2.ogg",
            ["A nap does sound nice."] = "dwarf-male\\npc_sleepToo_3.ogg",
            ["Up we go! Never gets old."] = "dwarf-male\\npc_taxi_1.ogg",
            ["Look at it all down there."] = "dwarf-male\\npc_taxi_2.ogg",
            ["A good gryphon is worth its weight in gold."] = "dwarf-male\\npc_taxi_3.ogg",
            ["Hold on tight!"] = "dwarf-male\\npc_taxi_4.ogg",
            ["I'll never get tired of this view."] = "dwarf-male\\npc_taxi_5.ogg",
            ["Don't look down. Actually, do. It's lovely."] = "dwarf-male\\npc_taxi_6.ogg",
            ["The wind up here! Hold on to your hat."] = "dwarf-male\\npc_taxi_7.ogg",
            ["Anytime."] = "dwarf-male\\npc_thanked_1.ogg",
            ["Happy to help."] = "dwarf-male\\npc_thanked_2.ogg",
            ["Don't mention it."] = "dwarf-male\\npc_thanked_3.ogg",
            ["{friend} thinks of you as {tier} now. I'm not surprised."] = "dwarf-male\\npc_tier_1.ogg",
            ["Making friends everywhere you go, aren't you?"] = "dwarf-male\\npc_tier_2.ogg",
            ["People really warm to you, don't they?"] = "dwarf-male\\npc_tier_3.ogg",
            ["That friendship's growing. Nice to see."] = "dwarf-male\\npc_tier_4.ogg",
            ["Hello!"] = "dwarf-male\\npc_waveBack_1.ogg",
            ["Hi there!"] = "dwarf-male\\npc_waveBack_2.ogg",
            ["Well, hello to you too."] = "dwarf-male\\npc_waveBack_3.ogg",
            ["Right back at you!"] = "dwarf-male\\npc_waveBack_4.ogg",
            ["Different roofs. I wonder who supervises this street. Give it a quiet moment; we may hear an opinion."] = "dwarf-male\\lore5510_zone_1.ogg",
            ["So this is {zone}."] = "dwarf-male\\npc_zone_1.ogg",
            ["{zone}, eh? Lead on."] = "dwarf-male\\npc_zone_2.ogg",
            ["I haven't been to {zone} in years."] = "dwarf-male\\npc_zone_3.ogg",
            ["{zone}. Stay sharp."] = "dwarf-male\\npc_zone_4.ogg",
            ["Ah, {zone}. Look at that view."] = "dwarf-male\\npc_zone_5.ogg",
            ["New place, new faces."] = "dwarf-male\\npc_zone_6.ogg",
            ["Keep your eyes open. I don't know these parts."] = "dwarf-male\\npc_zone_7.ogg",
            ["I've only ever heard stories about this place."] = "dwarf-male\\npc_zone_8.ogg",
            ["Look at it all. Worth the walk."] = "dwarf-male\\npc_zone_9.ogg",
            ["Smells different here. Not bad, just different."] = "dwarf-male\\npc_zone_10.ogg",
            ["I'd better remember the way back."] = "dwarf-male\\npc_zone_11.ogg",
            ["Well, this is a change of scenery."] = "dwarf-male\\npc_zone_12.ogg",
        },
        ["female"] = {
            ["And we're back! Nobody saw that, right?"] = "female\\alive_1.ogg",
            ["Welcome back!"] = "female\\npc_alive_1.ogg",
            ["Good as new. Better, even."] = "female\\alive_2.ogg",
            ["There you are. Gave me a fright."] = "female\\npc_alive_2.ogg",
            ["Alive again! Best feeling in the world!"] = "female\\alive_3.ogg",
            ["Back on your feet! Good."] = "female\\npc_alive_3.ogg",
            ["Back in one piece! Two pieces would have been worse."] = "female\\alive_4.ogg",
            ["Good as new. Well, nearly."] = "female\\npc_alive_4.ogg",
            ["We're back! Let's pretend that never happened."] = "female\\alive_5.ogg",
            ["Don't scare me like that again."] = "female\\npc_alive_5.ogg",
            ["Thank goodness. Being a ghost was very drafty."] = "female\\alive_6.ogg",
            ["Bravo! Encore!"] = "female\\applaudToo_1.ogg",
            ["Bravo!"] = "female\\npc_applaudToo_1.ogg",
            ["Yay! Clapping!"] = "female\\applaudToo_2.ogg",
            ["Well done!"] = "female\\npc_applaudToo_2.ogg",
            ["Encore!"] = "female\\npc_applaudToo_3.ogg",
            ["I'll just wait here, then. Zzz."] = "female\\away_1.ogg",
            ["I'll wait here."] = "female\\npc_away_1.ogg",
            ["Take your time. I'll guard our stuff."] = "female\\away_2.ogg",
            ["Take your time. I'm not going anywhere."] = "female\\npc_away_2.ogg",
            ["Don't worry about me. I'll count the stars."] = "female\\away_3.ogg",
            ["I'll keep an eye on things."] = "female\\npc_away_3.ogg",
            ["Away? I'll keep your spot warm."] = "female\\away_4.ogg",
            ["Off you go. I'll mind the spot."] = "female\\npc_away_4.ogg",
            ["If anyone asks, we're on a very important break."] = "female\\away_5.ogg",
            ["Wake me if anything exciting happens."] = "female\\npc_away_5.ogg",
            ["You're back! I wasn't sleeping. Much."] = "female\\back_1.ogg",
            ["There you are."] = "female\\npc_back_1.ogg",
            ["Oh! Hi! I was resting my eyes. Both of them."] = "female\\back_2.ogg",
            ["Welcome back."] = "female\\npc_back_2.ogg",
            ["Welcome back! I kept watch the whole time. Mostly."] = "female\\back_3.ogg",
            ["Ah, you're back. Shall we?"] = "female\\npc_back_3.ogg",
            ["There you are! I missed you."] = "female\\back_4.ogg",
            ["Ah, good. I was starting to talk to myself."] = "female\\npc_back_4.ogg",
            ["Back already? I was just getting to the good part of my dream."] = "female\\back_5.ogg",
            ["Ready? Me too."] = "female\\npc_back_5.ogg",
            ["Our bags are full! Maybe drop the rocks?"] = "female\\bagsFull_1.ogg",
            ["Full bags? I know a place where those turn into gold."] = "female\\lore9859_bagsFull_1.ogg",
            ["Your bags are bursting. Time to sell a few things."] = "female\\npc_bagsFull_1.ogg",
            ["No room! I'm not carrying it. I have tiny arms."] = "female\\bagsFull_2.ogg",
            ["No room left? I know a merchant or two."] = "female\\npc_bagsFull_2.ogg",
            ["Bags are stuffed. Time to visit a merchant. Bonus: new friend!"] = "female\\bagsFull_3.ogg",
            ["You're carrying half the countryside."] = "female\\npc_bagsFull_3.ogg",
            ["Too much stuff! Even I can't fit in there now."] = "female\\bagsFull_4.ogg",
            ["Your pack's going to split at the seams."] = "female\\npc_bagsFull_4.ogg",
            ["Full bags means we've been busy. Proud of us."] = "female\\bagsFull_5.ogg",
            ["You came to take me along! Oh, I like that. Let's go find something worth getting excited about, my friend."] = "female\\lore11026_befriended_1.ogg",
            ["You understand why the little things matter. I'm glad we're making some new memories together."] = "female\\lore11028_befriended_1.ogg",
            ["A new friend! I'll need a bigger table. That was going to happen anyway."] = "female\\lore11029_befriended_1.ogg",
            ["Come along! You have become my favorite person to share a completely unproductive complaint with. I can admit when a technique is beyond me, and I can admit that talking to leather has not made it ready any sooner. Your company, however, has improved the waiting considerably. That is a result I am happy to keep."] = "female\\lore1466_befriended_1.ogg",
            ["You have become someone I am happy to see before I have thought of anything to teach. Come along, friend. Tell me what you have been doing. I shall listen to the account before adding any footnotes. You may smile if I get ahead of myself. It helps me remember where we began."] = "female\\lore5144_befriended_1.ogg",
            ["You make it easy to ask a question of my own. I'm very glad to have your company."] = "female\\lore5177_befriended_1.ogg",
            ["You needn't find an excuse to visit. A smile and a little conversation are quite enough."] = "female\\lore5178_befriended_1.ogg",
            ["I will come along. You have become rather better company than I expected, and I see no reason to pretend otherwise. Tell me where we are going. I may offer an opinion or two, but you have had sufficient practice surviving those already."] = "female\\lore6376_befriended_1.ogg",
            ["You keep coming back. Not just when there's a reward waiting. I value that. Come along, my friend."] = "female\\lore6579_befriended_1.ogg",
            ["Off the market! I'm your buddy now. No refunds."] = "female\\lore9859_befriended_1.ogg",
            ["Why, thank you, kind {name}."] = "female\\bowBack_1.ogg",
            ["Likewise."] = "female\\npc_bowBack_1.ogg",
            ["The pleasure is mine."] = "female\\bowBack_2.ogg",
            ["An honor."] = "female\\npc_bowBack_2.ogg",
            ["After you. No, after you."] = "female\\bowBack_3.ogg",
            ["The pleasure's mine."] = "female\\npc_bowBack_3.ogg",
            ["{friend} is our Buddy now! Best day ever!"] = "female\\buddy_1.ogg",
            ["{friend} is your Buddy now? The more the merrier!"] = "female\\npc_buddy_1.ogg",
            ["We have a new Buddy! {friend}, welcome to the team!"] = "female\\buddy_2.ogg",
            ["Another Buddy. Should I be jealous?"] = "female\\npc_buddy_2.ogg",
            ["Buddy! {friend} is a real Buddy now!"] = "female\\buddy_3.ogg",
            ["Another Buddy! Your circle's getting crowded."] = "female\\npc_buddy_3.ogg",
            ["{friend} can come along now! Room for one more!"] = "female\\buddy_4.ogg",
            ["Good choice. I'd vouch for them."] = "female\\npc_buddy_4.ogg",
            ["A Buddy! Check the BuddyDex, {friend} can come with us now."] = "female\\buddy_5.ogg",
            ["Yay! What are we cheering for?"] = "female\\cheerAlong_1.ogg",
            ["Hooray!"] = "female\\npc_cheerAlong_1.ogg",
            ["Woo! Go us!"] = "female\\cheerAlong_2.ogg",
            ["Huzzah!"] = "female\\npc_cheerAlong_2.ogg",
            ["Hooray! For everything!"] = "female\\cheerAlong_3.ogg",
