            ["Hold on, it's weakening!"] = "female\\npc_combatLong_1.ogg",
            ["Still going! You can do it!"] = "female\\combatLong_2.ogg",
            ["Don't give up now!"] = "female\\npc_combatLong_2.ogg",
            ["Is it getting tired? I'm getting tired."] = "female\\combatLong_3.ogg",
            ["Steady. Steady."] = "female\\npc_combatLong_3.ogg",
