            ["This one's stubborn. Keep at it!"] = "female\\npc_combatLong_4.ogg",
            ["Maybe drink a potion? Just a thought!"] = "female\\combatLong_5.ogg",
            ["It's tiring! I can see it!"] = "female\\npc_combatLong_5.ogg",
