            ["Chin up. It'll be all right."] = "female\\npc_comforted_1.ogg",
            ["Want to talk about it? I'm a great listener."] = "female\\comforted_2.ogg",
            ["I'm here if you need me."] = "female\\npc_comforted_2.ogg",
            ["Sad? Here, have a tiny hug."] = "female\\comforted_3.ogg",
            ["Thank you. I needed that."] = "female\\npc_comforted_3.ogg",
            ["Dance party!"] = "female\\danceAlong_1.ogg",
            ["Ha! All right, I'll dance."] = "female\\npc_danceAlong_1.ogg",
            ["Ooh, I know this one!"] = "female\\danceAlong_2.ogg",
            ["I haven't danced in ages!"] = "female\\npc_danceAlong_2.ogg",
            ["Look at us go!"] = "female\\danceAlong_3.ogg",
            ["Well, if you insist!"] = "female\\npc_danceAlong_3.ogg",
            ["Nobody dances like a gnome."] = "female\\danceAlong_4.ogg",
            ["Watch my feet. Or don't."] = "female\\npc_danceAlong_4.ogg",
            ["Ow. Okay. That one's on the monster."] = "female\\died_1.ogg",
            ["Easy now. Let's get you back on your feet."] = "female\\npc_died_1.ogg",
            ["Oof. Want me to walk us back? I know the way."] = "female\\died_2.ogg",
            ["That looked like it hurt."] = "female\\npc_died_2.ogg",
            ["We'll get them next time, {name}."] = "female\\died_3.ogg",
            ["Don't worry. Happens to the best of us."] = "female\\npc_died_3.ogg",
            ["Well. That happened."] = "female\\died_4.ogg",
            ["We'll come back stronger."] = "female\\npc_died_4.ogg",
            ["I didn't see anything. Nobody saw anything."] = "female\\died_5.ogg",
            ["Oh, that's not good."] = "female\\npc_died_5.ogg",
            ["Spirit healers are just friends we haven't thanked yet."] = "female\\died_6.ogg",
            ["Well. That could have gone better."] = "female\\npc_died_6.ogg",
            ["Nobody tell the BuddyDex about this one."] = "female\\died_7.ogg",
            ["Let's agree that one didn't count."] = "female\\npc_died_7.ogg",
            ["At least we look good as ghosts."] = "female\\died_8.ogg",
            ["Lie still. I'll keep watch."] = "female\\npc_died_8.ogg",
            ["I'm not crying. You're crying."] = "female\\died_9.ogg",
            ["Okay, new plan: less of that."] = "female\\died_10.ogg",
            ["On the bright side, we don't have to pay for repairs. Oh wait, we do."] = "female\\died_11.ogg",
            ["A dungeon! Stay close. Not too close. Medium close."] = "female\\dungeon_1.ogg",
            ["Keep close in here."] = "female\\npc_dungeon_1.ogg",
            ["Into the dark we go! I'll hold the imaginary torch."] = "female\\dungeon_2.ogg",
            ["I don't like the look of this place."] = "female\\npc_dungeon_2.ogg",
            ["Dungeons always smell a little funny, don't they?"] = "female\\dungeon_3.ogg",
            ["Watch your step. And your back."] = "female\\npc_dungeon_3.ogg",
            ["Remember: we pull together, we win together. I mostly cheer together."] = "female\\dungeon_4.ogg",
            ["It's dark in here. I don't love the dark."] = "female\\npc_dungeon_4.ogg",
            ["Ooh, spooky. Let's make some brave memories."] = "female\\dungeon_5.ogg",
            ["Stay together. Nobody wander off."] = "female\\npc_dungeon_5.ogg",
            ["Look at these guns! Your guns!"] = "female\\flexBack_1.ogg",
            ["Very impressive."] = "female\\npc_flexBack_1.ogg",
            ["Strong like a gnome!"] = "female\\flexBack_2.ogg",
            ["Don't hurt yourself."] = "female\\npc_flexBack_2.ogg",
            ["We are so mighty."] = "female\\flexBack_3.ogg",
            ["Put those away before someone gets hurt."] = "female\\npc_flexBack_3.ogg",
            ["New gear! And it fits me perfectly. Funny how that works."] = "female\\gear_1.ogg",
            ["That looks good on you."] = "female\\npc_gear_1.ogg",
            ["Ooh, shiny! We look fantastic."] = "female\\gear_2.ogg",
            ["New armor? Very sharp."] = "female\\npc_gear_2.ogg",
            ["Do you like it? I like it. We have great taste."] = "female\\gear_3.ogg",
            ["You'll turn heads in that."] = "female\\npc_gear_3.ogg",
            ["Check us out! Spin for the crowd!"] = "female\\gear_4.ogg",
            ["Shiny! Did you polish that yourself?"] = "female\\npc_gear_4.ogg",
            ["That's a good look on us. A very good look."] = "female\\gear_5.ogg",
            ["That suits you. Very heroic."] = "female\\npc_gear_5.ogg",
            ["New armor? I feel sturdier already."] = "female\\gear_6.ogg",
            ["Now you look the part."] = "female\\npc_gear_6.ogg",
            ["Ooh la la."] = "female\\gear_7.ogg",
            ["Matching outfits! Always matching outfits!"] = "female\\gear_8.ogg",
            ["I'd say it brings out my eyes, but they're your eyes."] = "female\\gear_9.ogg",
            ["Fancy! Should we go show somebody?"] = "female\\gear_10.ogg",
            ["Corpse run! My favorite. Not my favorite."] = "female\\ghost_1.ogg",
            ["Come on, your body's this way."] = "female\\npc_ghost_1.ogg",
            ["I can see through my hands! Our hands!"] = "female\\ghost_2.ogg",
            ["I'll walk with you. Don't mind the chill."] = "female\\npc_ghost_2.ogg",
            ["Which way was the body again?"] = "female\\ghost_3.ogg",
            ["You look a bit see-through. It's fine. Mostly fine."] = "female\\npc_ghost_3.ogg",
            ["Spooky. I feel very spooky right now."] = "female\\ghost_4.ogg",
            ["Follow the road. I'll be right here."] = "female\\npc_ghost_4.ogg",
            ["Walk it off, {name}. Literally."] = "female\\ghost_5.ogg",
            ["Is it cold, being a ghost? You look cold."] = "female\\npc_ghost_5.ogg",
            ["Being a ghost is fine. It's the walking I mind."] = "female\\ghost_6.ogg",
            ["Hi, {name}! It's me, you! Well, a smaller you."] = "female\\greet_1.ogg",
            ["There you are! Come along. I've been staring at one stubborn little part, and my brain could use a run around."] = "female\\lore11026_greet_1.ogg",
            ["Ready! New things to see, and a bag I've checked for holes. Twice."] = "female\\lore11028_greet_1.ogg",
            ["An expedition! Excellent. Keep an eye out for exceptionally large poultry."] = "female\\lore11029_greet_1.ogg",
            ["Welcome! Have you come to learn leatherworking, or to keep me company while this hide decides to be useful? I have already tried asking politely. It remains unmoved. If your questions are beyond what I can teach, I will point you toward Fimble. Until then, we can at least get your hands working."] = "female\\lore1466_greet_1.ogg",
            ["There you are! How has your day been? I am asking that first, before I begin explaining something you may not have asked about. It seemed a useful improvement. I wrote a note to remind myself, and I am trying very hard to let that note remain a single sentence."] = "female\\lore5144_greet_1.ogg",
            ["A walk would be lovely. Tell me what you've been wondering about lately."] = "female\\lore5177_greet_1.ogg",
            ["A little walk sounds pleasant. Are all those bottles closed properly?"] = "female\\lore5178_greet_1.ogg",
            ["There you are. I trust you have given some thought to what you want before coming to ask about it. Sit a moment if you like. I am examining a promising corner of toast. You will be pleased to know that this particular examination requires no demon at all."] = "female\\lore6376_greet_1.ogg",
            ["An outing? Good. Tell me what you've seen. Useful information, if possible. I have quite enough speeches waiting at home."] = "female\\lore6579_greet_1.ogg",
            ["Out of the auction house! So this is what daylight looks like."] = "female\\lore9859_greet_1.ogg",
            ["Lead the way, {name}."] = "female\\npc_greet_1.ogg",
            ["Ready for an adventure, {name}? I packed snacks. Tiny ones."] = "female\\greet_2.ogg",
            ["Lot number one: me. Sold, to the adventurer!"] = "female\\lore9859_greet_2.ogg",
            ["Glad to come along, {name}!"] = "female\\npc_greet_2.ogg",
            ["There you are, {name}! I was starting to think you'd gone without me."] = "female\\greet_3.ogg",
            ["Where are we off to today?"] = "female\\npc_greet_3.ogg",
            ["Hello again, {name}! Same armor, same face, half the height."] = "female\\greet_4.ogg",
            ["I told the others I'd be out for a while. Let's make it count."] = "female\\npc_greet_4.ogg",
            ["Reporting for duty! Pocket-sized, fully charged."] = "female\\greet_5.ogg",
            ["It's good to get away from the counter for once."] = "female\\npc_greet_5.ogg",
            ["Good to see you, {name}! Shall we go befriend somebody?"] = "female\\greet_6.ogg",
            ["Ready when you are, {name}."] = "female\\npc_greet_6.ogg",
            ["I polished my boots while you were gone. Well, your boots. Our boots."] = "female\\greet_7.ogg",
            ["Some fresh air will do me good."] = "female\\npc_greet_7.ogg",
            ["Oh good, you're back. I ran out of things to say to myself."] = "female\\greet_8.ogg",
            ["Don't walk too fast. I'm not used to all this adventuring."] = "female\\npc_greet_8.ogg",
            ["Ta-da! Your favorite gnome, at your service."] = "female\\greet_9.ogg",
            ["Well met, {name}! Good to see a friendly face."] = "female\\npc_greet_9.ogg",
            ["Let's make today a good one, {name}."] = "female\\greet_10.ogg",
            ["Right behind you. Where to first?"] = "female\\npc_greet_10.ogg",
            ["I dreamed we were tall. It was terrifying."] = "female\\greet_11.ogg",
            ["I packed a lunch. Just in case."] = "female\\npc_greet_11.ogg",
            ["Back in action! Where to first?"] = "female\\greet_12.ogg",
            ["Off on an adventure! Don't tell my boss."] = "female\\npc_greet_12.ogg",
            ["Hey hey! Did you miss me? Don't answer that."] = "female\\greet_13.ogg",
            ["Fresh boots, fresh start. Let's go."] = "female\\npc_greet_13.ogg",
            ["You look great today. I would know. I look exactly like you."] = "female\\greet_14.ogg",
            ["I've been looking forward to this all week."] = "female\\npc_greet_14.ogg",
            ["Another day, another adventure, another friend to make!"] = "female\\greet_15.ogg",
            ["Stretching! Gnome legs need a warm-up."] = "female\\greet_16.ogg",
            ["Good afternoon, {name}! Perfect time for a little wandering."] = "female\\greetAfternoon_1.ogg",
            ["Afternoon! I've been saving up chatter all morning."] = "female\\greetAfternoon_2.ogg",
            ["Evening, {name}! Perfect time for a little adventuring."] = "female\\greetEvening_1.ogg",
            ["The lamps are coming on. Cozy adventuring hours!"] = "female\\greetEvening_2.ogg",
            ["A whole evening ahead of us. Let's not waste it."] = "female\\greetEvening_3.ogg",
            ["Good morning, {name}! The early gnome gets the worm. I don't want the worm."] = "female\\greetMorning_1.ogg",
            ["Morning already? I just got comfortable."] = "female\\greetMorning_2.ogg",
            ["Rise and shine! Somebody out there needs a friend today."] = "female\\greetMorning_3.ogg",
            ["A fresh morning, a fresh start. Let's go meet people!"] = "female\\greetMorning_4.ogg",
            ["Up late, {name}? Me too. I'm always up when you're up."] = "female\\greetNight_1.ogg",
            ["Night owls, the both of us. Hoo hoo."] = "female\\greetNight_2.ogg",
            ["It's late! Just one more quest. Then another. You know how it goes."] = "female\\greetNight_3.ogg",
            ["The best friendships are made after midnight. I read that somewhere. Maybe."] = "female\\greetNight_4.ogg",
            ["A group! More friends! This is the best day."] = "female\\group_1.ogg",
            ["More company! Wonderful."] = "female\\npc_group_1.ogg",
            ["Ooh, company! Hi, everyone. I'm the small one."] = "female\\group_2.ogg",
            ["Strength in numbers."] = "female\\npc_group_2.ogg",
            ["Party time! The other kind of party."] = "female\\group_3.ogg",
            ["New faces! Hello, everyone."] = "female\\npc_group_3.ogg",
            ["Teamwork makes the dream work. And the quests go faster."] = "female\\group_4.ogg",
            ["A whole party. Now it's an adventure."] = "female\\npc_group_4.ogg",
            ["New group! I'll try not to steal the spotlight."] = "female\\group_5.ogg",
            ["Home, here we come!"] = "female\\hearth_1.ogg",
            ["Home again!"] = "female\\npc_hearth_1.ogg",
            ["Hearthing! See you there. Well, I'll see you everywhere."] = "female\\hearth_2.ogg",
            ["Off to the inn. My treat. Well, your treat."] = "female\\npc_hearth_2.ogg",
            ["Back to the inn! I call the comfy chair."] = "female\\hearth_3.ogg",
            ["Home sweet home."] = "female\\npc_hearth_3.ogg",
            ["Poof! I love that part."] = "female\\hearth_4.ogg",
            ["Back to a warm bed. Finally."] = "female\\npc_hearth_4.ogg",
            ["Aww! Hug accepted!"] = "female\\hugged_1.ogg",
            ["Oh! Well. That's nice."] = "female\\npc_hugged_1.ogg",
            ["You're the best, {name}."] = "female\\hugged_2.ogg",
            ["Aw, thank you."] = "female\\npc_hugged_2.ogg",
            ["A hug! From me, to me!"] = "female\\hugged_3.ogg",
            ["Oh, you big softie."] = "female\\npc_hugged_3.ogg",
            ["Did you know gnomes invented most things? Look it up. Actually, don't."] = "female\\idle_1.ogg",
            ["Every petal opens in order. Well, that is the idea. The last one still sticks. Don't laugh until you've seen how tiny it is."] = "female\\lore11026_idle_1.ogg",
            ["Equations and a chili recipe. I couldn't tell you which my family would argue about more."] = "female\\lore11028_idle_1.ogg",
            ["The turkey is a separate engineering problem. I refuse to let it delay the baster."] = "female\\lore11029_idle_1.ogg",
            ["I started calling one particularly stubborn hide Your Slowness. It seemed fitting for something that expects everyone else to wait upon it. Since then I have promoted it several times. No improvement whatsoever. Still, a student laughed, and the waiting became rather less tedious. That is more than the hide has managed for us."] = "female\\lore1466_idle_1.ogg",
            ["I wrote myself a reminder to keep an explanation short. Then I thought of an important exception and put it underneath. There were several other exceptions. By the time I finished, the reminder needed an explanation of its own. A useful example, although it has not yet solved the original problem."] = "female\\lore5144_idle_1.ogg",
            ["I keep the questions I couldn't answer. It would be a shame to stop learning just because I teach."] = "female\\lore5177_idle_1.ogg",
            ["Plain water. Excellent clarity, no surprises. I remain a devoted customer."] = "female\\lore5178_idle_1.ogg",
            ["A good crisp corner. That is what I am looking for. No incantation, no hidden ingredient, no extraordinary consequence. I like the crunch. You would be surprised how often a perfectly ordinary pleasure has to defend itself against someone else's imagination."] = "female\\lore6376_idle_1.ogg",
            ["The flags? For when we have our home back. Yes, I know there's work left. That's why they're still drawings."] = "female\\lore6579_idle_1.ogg",
            ["Linen cloth is up again. I can feel it."] = "female\\lore9859_idle_1.ogg",
            ["Nice day for it."] = "female\\npc_idle_1.ogg",
            ["Your armor looks great on me. On you. On us."] = "female\\idle_2.ogg",
            ["Buckler had better not touch my ledger while I'm gone."] = "female\\lore9859_idle_2.ogg",
            ["{zone} is lovely this time of year."] = "female\\npc_idle_2.ogg",
            ["Is it just me, or is everything really tall today?"] = "female\\idle_3.ogg",
            ["Somewhere, someone just undercut by one copper."] = "female\\lore9859_idle_3.ogg",
            ["Don't mind me. I'm enjoying the company."] = "female\\npc_idle_3.ogg",
            ["If you need me, I'll be right here. Standing. Being adorable."] = "female\\idle_4.ogg",
            ["You know, I don't get out nearly enough."] = "female\\npc_idle_4.ogg",
            ["{zone} sure is nice this time of year."] = "female\\idle_5.ogg",
            ["My feet are already sore. In a good way."] = "female\\npc_idle_5.ogg",
            ["Fun fact: I'm exactly as brave as you are, just closer to the ground."] = "female\\idle_6.ogg",
            ["I wonder how things are back home without me."] = "female\\npc_idle_6.ogg",
            ["Let's go make some friends! I'll do the waving."] = "female\\idle_7.ogg",
            ["Every road looks different when you're not working."] = "female\\npc_idle_7.ogg",
            ["We've made {friends} friends so far. Who's next?"] = "female\\idle_8.ogg",
            ["Have you ever just stopped and listened to the wind?"] = "female\\npc_idle_8.ogg",
            ["Just practicing my moves."] = "female\\idle_9.ogg",
            ["I could get used to this."] = "female\\npc_idle_9.ogg",
            ["I wonder what the gryphons think about all day."] = "female\\idle_10.ogg",
            ["Don't tell anyone, but this beats standing in one spot all day."] = "female\\npc_idle_10.ogg",
            ["Somewhere out there, a merchant is waiting to be our best friend."] = "female\\idle_11.ogg",
            ["If you need a hand, just say the word."] = "female\\npc_idle_11.ogg",
            ["Gnomish proverb: the smaller the gnome, the bigger the plan."] = "female\\idle_12.ogg",
            ["Good company makes the miles shorter."] = "female\\npc_idle_12.ogg",
            ["Do you think I could ride a squirrel? Asking for me."] = "female\\idle_13.ogg",
            ["Mind if I stretch? Old bones."] = "female\\npc_idle_13.ogg",
            ["Hmm. Hmmmm. Nope, lost the thought."] = "female\\idle_14.ogg",
            ["Getting late. The stars will be out soon."] = "female\\npc_idle_14.ogg",
            ["I counted the clouds. There were some."] = "female\\idle_15.ogg",
            ["Quiet night. I like quiet nights."] = "female\\npc_idle_15.ogg",
            ["Sometimes I think about Gnomeregan. Then I think about something nicer."] = "female\\idle_16.ogg",
            ["We've been at it for a while. You're tireless, you know that?"] = "female\\npc_idle_16.ogg",
            ["If I had a coin for every step I take, I'd have a lot of very tiny coins."] = "female\\idle_17.ogg",
            ["I used to wonder what was past the next hill. Now I know: another hill."] = "female\\npc_idle_17.ogg",
            ["Look at us. A matching set!"] = "female\\idle_18.ogg",
            ["Do you ever get used to all this walking?"] = "female\\npc_idle_18.ogg",
