            ["I've heard stories about you, you know. Some of them are even nice."] = "female\\npc_idle_19.ogg",
            ["You know what this place needs? More gnomes."] = "female\\idle_20.ogg",
            ["Smell that? Somebody's cooking something good nearby."] = "female\\npc_idle_20.ogg",
            ["Every NPC is just a friend we haven't met yet."] = "female\\idle_21.ogg",
            ["If anyone asks, I'm on important business."] = "female\\npc_idle_21.ogg",
            ["I've been practicing my /bow. Want to see? Too late, I'm shy now."] = "female\\idle_22.ogg",
            ["You're easy company. I mean that kindly."] = "female\\npc_idle_22.ogg",
