            ["I bet you could heal a paper cut from across the room."] = "female\\idle_39.ogg",
            ["Morning air's the best air."] = "female\\npc_idle_39.ogg",
            ["I promise I'm not hiding. I'm just short."] = "female\\idle_40.ogg",
            ["Early start, eh? I approve."] = "female\\npc_idle_40.ogg",
