            ["The light's going gold. Best time of day."] = "female\\npc_idle_41.ogg",
            ["Where's your pet? I want to pet the pet."] = "female\\idle_42.ogg",
            ["Stars are out. Makes you feel small, doesn't it?"] = "female\\npc_idle_42.ogg",
            ["Every time a bow twangs, I duck. Old habit."] = "female\\idle_43.ogg",
            ["Shouldn't we both be in bed by now?"] = "female\\npc_idle_43.ogg",
