            ["Loch Modan is so pretty. Let's never go swimming in it."] = "female\\idle_58.ogg",
            ["The trees in Teldrassil are so tall I'm getting a neck ache."] = "female\\idle_59.ogg",
            ["Darnassus is lovely, but I keep getting lost."] = "female\\idle_60.ogg",
            ["The Wetlands! My boots are already soggy."] = "female\\idle_61.ogg",
