            ["The Barrens. There's a lot of it, isn't there."] = "female\\idle_63.ogg",
            ["It's late. The stars are out. Even gnomes get sleepy."] = "female\\idle_64.ogg",
            ["Nice morning for it. Whatever it is."] = "female\\idle_65.ogg",
